"use strict";const flexDirection=new Set(["row","row-reverse","column","column-reverse"]),flexWrap=new Set(["nowrap","wrap","wrap-reverse"]);module.exports=function(e){let r={direction:"",wrap:""};return e.walk(({value:e})=>{flexDirection.has(e.toLowerCase())?r.direction=e:flexWrap.has(e.toLowerCase())&&(r.wrap=e)}),`${r.direction} ${r.wrap}`.trim()};